// Keep the standalone packaged desktop policy identical to the browser planner.
import fs from 'node:fs/promises';
import '../app/source-page-plan.js';
const {titleInfo,wrapTitle}=globalThis.ThreadsPagePlan;
await fs.writeFile(new URL('../desktop/title-layout.cjs',import.meta.url),
  "'use strict';\n// Generated by scripts/sync-title-layout.mjs from the browser title policy.\n"+
  titleInfo.toString()+'\n'+wrapTitle.toString()+'\nmodule.exports={titleInfo,wrapTitle};\n');
